INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('code-task-lease-lost-write', 'a code-loop lane whose lease lapsed during a slow model call overwrites a task another lane already advanced', 'claim() leases a row for LEASE_MS (90 s) while a propose step on a slow rung runs longer; the step''s saves were unconditional UPDATE ... WHERE id = ?, so the stale lane''s step verify and patch-less ctx landed on a ready_to_publish task, and its failure path reset a ready task to queued', 'qnfo-code-orchestrator 0.18.23 LEASE-FENCE-1: every save of a step is fenced on status queued and the lease the lane holds; a refused save ends the step with code-task.lease-lost and writes nothing, and settle() checks the lease before it files a handoff issue', 'no code task failed at publish for a missing patch in the last 60 minutes', 'fm-code-task-lease-lost-write', '2026-10-19', NULL, 'a model call longer than the 90 s lease with another tick running', 'publish_failed "task has no patch in ctx.patch" on tasks the orchestrator had logged ready; the same task handed off twice', 'every code task: each lost write discards a finished patch and the model calls behind it');
