 ('fm-code-task-lease-lost-write', NULL, 'LEASE-FENCE-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM code_tasks WHERE status IN (''publish_failed'', ''failed'') AND last_error LIKE ''%no patch in ctx.patch%'' AND updated_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0);
